SELECT analytics_order_facts.customer_segment, SUM(analytics_order_facts.net_revenue) / CAST(NULLIF(COUNT(DISTINCT analytics_order_facts.order_id), 0) AS DECIMAL) AS average_order_value FROM analytics_order_facts WHERE analytics_order_facts.year = 2023 AND analytics_order_facts.month = 7 AND analytics_order_facts.region = 'South' AND analytics_order_facts.channel = 'marketplace' GROUP BY analytics_order_facts.customer_segment ORDER BY average_order_value DESC, analytics_order_facts.customer_segment ASC LIMIT 12
